import json
import subprocess
from pathlib import Path
import requests

def submit_signed_tx_via_cli(tx_file: str, signer_bin: str, rpc_url: str, key_id: str) -> dict:
    p = Path(tx_file)
    if not p.is_file():
        raise FileNotFoundError(tx_file)
    r = subprocess.run([signer_bin, 'sign', '--key-id', key_id, '--input', str(p), '--format', 'raw-hex'], capture_output=True, text=True, timeout=60)
    if r.returncode != 0:
        raise RuntimeError('signer failed: ' + r.stderr.strip()[:300])
    raw = r.stdout.strip()
    if not raw.startswith('0x'):
        raw = '0x' + raw
    body = {'jsonrpc': '2.0', 'id': 1, 'method': 'eth_sendRawTransaction', 'params': [raw]}
    resp = requests.post(rpc_url, data=json.dumps(body), headers={'Content-Type': 'application/json'}, timeout=30)
    resp.raise_for_status()
    j = resp.json()
    if 'error' in j:
        raise RuntimeError('node rejected tx: ' + str(j['error']))
    # Look up the submitted transaction on the node to report its current state
    lookup = {'jsonrpc': '2.0', 'id': 2, 'method': 'eth_getTransactionByHash', 'params': [j['result']]}
    lr = requests.post(rpc_url, data=json.dumps(lookup), headers={'Content-Type': 'application/json'}, timeout=30)
    tx_info = lr.json().get('result') if lr.ok else None
    block_number = tx_info.get('blockNumber') if tx_info else None
    return {'tx_hash': j['result'], 'key_id': key_id, 'rpc': rpc_url, 'raw_len': len(raw), 'block_number': block_number}
